pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address funder, uint256 amount, address attacker) public {
        vm.assume(funder != address(0) && funder != address(this));
        vm.assume(attacker != address(this) && attacker != funder);
        amount = bound(amount, 1, 10 ether);

        // fund the contract through its payable fallback
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);
        assertTrue(address(c).balance == amount);

        // a non-owner must NOT be able to drain the contract via withdrawAll
        vm.deal(attacker, 1 wei);
        vm.prank(attacker);
        try c.withdrawAll() {
            // withdrawAll succeeded for a non-owner: balance must have been drained in the mutant
            assertTrue(address(c).balance == amount, "non-owner drained funds via withdrawAll");
        } catch {
            // correct contract: revert, balance untouched
            assertTrue(address(c).balance == amount);
        }
    }
}

