        vm.assume(caller != address(this));
        vm.assume(caller != address(c));
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the contract with the fuzzed amount
        vm.deal(address(c), amount);

        uint256 callerBefore = caller.balance;

        vm.prank(caller);
        try c.withdrawAll() {
            // In the reference, only the owner (this test contract) succeeds;
            // caller here is never the owner, so success should not enrich caller.
