pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // admissible domain: a caller distinct from the owner (owner is this test
        // contract, since setUp ran with msg.sender == address(this)) and any amount
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        amount = bound(amount, 0, type(uint256).max / 2);

        // fund the contract through its payable fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        c.fallback{value: amount}();

        uint256 balBefore = address(c).balance;
        uint256 depositsBefore = c.depositsCount();
        vm.deal(actor, 1 wei);

        // a non-owner attempts to drain everything
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // general rule: a non-owner can never successfully withdrawAll, so the
        // contract's balance and deposit record must be unchanged
        assertTrue(!ok && address(c).balance == balBefore && c.depositsCount() == depositsBefore);
    }
}

