        // fund c via its payable fallback
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);

        // target is this test contract, which has no receive/fallback:
        // the low-level call inside sendMoney fails.
        // On P the require reverts the whole transaction; on M it does not.
        c.sendMoney(address(this), amount);

        // If execution reaches here, the failed send was swallowed (mutant):
        // c's balance was drained to 0 instead of staying at `amount`.
        assert(address(c).balance == amount);
    }
}

